select OBJECT_NAME,OBJECT_TYPE,STATUS from USER_OBJECTS where OBJECT_NAME in('RRL_ST_DEFER_CASE_WAIT','RRL_ST_DEFER_PHYSICAL','RRL_ST_DEFER_API','RRL_ST_DEFER_WAIT_API','RRL_STOCK_CASE_MOVE_CMD','RRL_STOCK_POSTING_API');
select NAME,TYPE,LINE,TEXT from USER_ERRORS where NAME not like 'BIN$%'order by NAME,SEQUENCE;
select TASK_ID,CASE_TASK_ID from RRL_ST_DEFER_WAIT_PLAN where CASE_TASK_ID is not null;
